--
-- Table structure for table `movimentos`
--

DROP TABLE IF EXISTS `movimentos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `movimentos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `condominio_id` bigint unsigned NOT NULL,
  `morador_id` bigint unsigned DEFAULT NULL,
  `locker_id` bigint unsigned DEFAULT NULL,
  `id_externo` bigint unsigned DEFAULT NULL,
  `guid` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `morador_nome` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bloco` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `apartamento` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `porta` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `senha` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `codigo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `entregador` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `data_entrada` timestamp NULL DEFAULT NULL,
  `data_retirada` timestamp NULL DEFAULT NULL,
  `status` enum('pendente','retirada','expirada','erro') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pendente',
  `tablet_nome` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payload` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `movimentos_condominio_id_foreign` (`condominio_id`),
  KEY `movimentos_morador_id_foreign` (`morador_id`),
  KEY `movimentos_locker_id_foreign` (`locker_id`),
  KEY `movimentos_id_externo_index` (`id_externo`),
  KEY `movimentos_codigo_index` (`codigo`),
  KEY `movimentos_data_entrada_index` (`data_entrada`),
  KEY `movimentos_status_index` (`status`),
  CONSTRAINT `movimentos_condominio_id_foreign` FOREIGN KEY (`condominio_id`) REFERENCES `condominios` (`id`) ON DELETE CASCADE,
  CONSTRAINT `movimentos_locker_id_foreign` FOREIGN KEY (`locker_id`) REFERENCES `lockers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `movimentos_morador_id_foreign` FOREIGN KEY (`morador_id`) REFERENCES `moradores` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=999 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

